describe('Search Bar Mobile Expansion on Focus', () => {
  beforeEach(() => {
    cy.viewport('iphone-x');
    cy.visit('/');
    cy.get('[data-testid="search-bar"]').as('searchBar');
  });

  it('should expand search bar when focused on mobile viewport', () => {
    cy.get('@searchBar').should('have.css', 'width').and('match', /^\d+px$/);
    const initialWidth = cy.get('@searchBar').invoke('width');

    cy.get('@searchBar').click();
    cy.get('@searchBar').should('have.focus');

    cy.get('@searchBar').invoke('width').then((expandedWidth) => {
      initialWidth.then((initial) => {
        expect(expandedWidth).to.be.greaterThan(initial);
      });
    });
  });

  it('should collapse search bar when focus is lost on mobile viewport', () => {
    cy.get('@searchBar').click();
    cy.get('@searchBar').should('have.focus');

    cy.get('@searchBar').invoke('width').then((expandedWidth) => {
      cy.get('body').click(0, 0);
      cy.get('@searchBar').should('not.have.focus');

      cy.get('@searchBar').invoke('width').then((collapsedWidth) => {
        expect(collapsedWidth).to.be.lessThan(expandedWidth);
      });
    });
  });

  it('should maintain expanded state while typing in search bar on mobile', () => {
    cy.get('@searchBar').click();
    cy.get('@searchBar').type('test query');

    cy.get('@searchBar').invoke('width').then((widthWhileTyping) => {
      cy.get('@searchBar').should('have.value', 'test query');
      cy.get('@searchBar').invoke('width').then((currentWidth) => {
        expect(currentWidth).to.equal(widthWhileTyping);
      });
    });
  });

  it('should handle rapid focus and blur cycles on mobile', () => {
    for (let i = 0; i < 3; i++) {
      cy.get('@searchBar').click();
      cy.get('@searchBar').should('have.focus');
      cy.get('body').click(0, 0);
      cy.get('@searchBar').should('not.have.focus');
    }

    cy.get('@searchBar').should('be.visible');
  });

  it('should not expand search bar on desktop viewport', () => {
    cy.viewport(1920, 1080);
    cy.visit('/');

    cy.get('@searchBar').invoke('width').then((desktopWidth) => {
      cy.get('@searchBar').click();
      cy.get('@searchBar').invoke('width').then((focusedWidth) => {
        expect(focusedWidth).to.equal(desktopWidth);
      });
    });
  });

  it('should handle search bar expansion with keyboard navigation on mobile', () => {
    cy.get('@searchBar').tab();
    cy.get('@searchBar').should('have.focus');

    cy.get('@searchBar').invoke('width').then((expandedWidth) => {
      cy.get('@searchBar').invoke('width').then((initial) => {
        expect(expandedWidth).to.be.greaterThan(initial);
      });
    });
  });

  it('should display placeholder text clearly in expanded state on mobile', () => {
    cy.get('@searchBar').should('have.attr', 'placeholder');

    cy.get('@searchBar').click();
    cy.get('@searchBar').should('have.focus');

    cy.get('@searchBar').invoke('attr', 'placeholder').then((placeholder) => {
      expect(placeholder).to.not.be.empty;
    });

    cy.get('@searchBar').should('be.visible');
  });
});
